package erratum

import (
	"errors"
	"fmt"
)

// Use opens a resource via opener (retrying while it fails with a
// TransientError), calls Frob(input) on the resource, and ensures the
// resource is closed exactly once in all cases. If Frob panics, the panic
// value is recovered: if it is a FrobError, Defrob is called with the
// FrobError's defrobTag before the resource is closed.
func Use(opener ResourceOpener, input string) error {
	var resource Resource
	var err error
	for {
		resource, err = opener()
		if err == nil {
			break
		}
		var transientErr TransientError
		if !errors.As(err, &transientErr) {
			return err
		}
	}

	// Close must run after the recover below (defers run LIFO), so that
	// Defrob is called before Close when Frob panics with a FrobError.
	defer resource.Close()

	defer func() {
		if r := recover(); r != nil {
			switch fe := r.(type) {
			case FrobError:
				resource.Defrob(fe.defrobTag)
			case *FrobError:
				resource.Defrob(fe.defrobTag)
			}
			if e, ok := r.(error); ok {
				err = e
			} else {
				err = fmt.Errorf("panic: %v", r)
			}
		}
	}()

	resource.Frob(input)
	return err
}

